def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Splits a string of nested parentheses into separate balanced groups.
    Spaces are ignored. Raises ValueError on invalid input.
    """
    result = []
    current = []
    depth = 0

    for ch in paren_string:
        if ch.isspace():
            continue
        if ch == '(' or ch == ')':
            current.append(ch)
            depth += 1 if ch == '(' else -1
            if depth < 0:
                raise ValueError("Unbalanced parentheses: too many closing brackets.")
            if depth == 0:
                result.append(''.join(current))
                current.clear()
        else:
            raise ValueError(f"Invalid character '{ch}' in input.")

    if depth != 0:
        raise ValueError("Unbalanced parentheses: unmatched opening brackets remain.")
    return result

def below_zero(operations: list[int]) -> bool:
    """
    Return True if the cumulative balance ever falls below zero.
    """
    if not isinstance(operations, (list, tuple)):
        raise TypeError("operations must be a list or tuple of numbers")

    balance = 0
    for op in operations:
        if not isinstance(op, (int, float)):
            raise ValueError(f"operation must be numeric, got {type(op).__name__}")
        balance += op
        if balance < 0:
            return True
    return False

